/** @CustomParams
{
    "sitemaps": {
        "type": "string",
        "title": "Sitemaps (JSON)",
        "required": true,
        "description": "JSON array of sitemaps from the list_sitemaps node"
    }
}
*/
export default async function run({ data }) {
  const raw = data.sitemaps;
  const list = Array.isArray(raw) ? raw : JSON.parse(raw || "[]");

  const sitemaps = list.map(s => {
    const contents = s.contents || [];
    return {
      path:            s.path,
      type:            s.type,
      is_index:        Boolean(s.isSitemapsIndex),
      is_pending:      Boolean(s.isPending),
      last_submitted:  s.lastSubmitted,
      last_downloaded: s.lastDownloaded || null,
      errors:          Number(s.errors   || 0),
      warnings:        Number(s.warnings || 0),
      submitted_urls:  contents.reduce((n, c) => n + Number(c.submitted || 0), 0)
    };
  });

  const problems = sitemaps
    .filter(s => s.errors > 0 || s.warnings > 0 || s.is_pending || !s.last_downloaded)
    .map(s => ({
      path: s.path,
      issue: s.errors > 0   ? `${s.errors} errors`
           : s.warnings > 0 ? `${s.warnings} warnings`
           : s.is_pending   ? "Pending processing"
           : "Never downloaded by Google"
    }));

  return {
    total_sitemaps:       sitemaps.length,
    total_submitted_urls: sitemaps.reduce((n, s) => n + s.submitted_urls, 0),
    has_problems:         problems.length > 0,
    problems,
    sitemaps
  };
}

