/** @CustomParams
{
    "rows": {
        "type": "string",
        "title": "Rows (JSON)",
        "required": true,
        "description": "JSON array of rows from the search analytics node"
    }
}
*/
export default async function run({ data }) {
  const parse = (v) => {
    if (Array.isArray(v)) return v;
    if (v == null || v === '' || v === 'null' || v === 'undefined') return [];
    try { const out = JSON.parse(v); return Array.isArray(out) ? out : []; } catch (e) { return []; }
  };
  const rows = parse(data.rows);

  const MIN_POSITION    = 8;
  const MAX_POSITION    = 20;
  const MIN_IMPRESSIONS = 50;
  const LIMIT           = 50;

  const opportunities = rows
    .filter(r =>
      r.position >= MIN_POSITION &&
      r.position <= MAX_POSITION &&
      r.impressions >= MIN_IMPRESSIONS
    )
    .map(r => ({
      query:       r.keys[0],
      position:    Math.round(r.position * 10) / 10,
      impressions: r.impressions,
      clicks:      r.clicks,
      ctr_pct:     Math.round(r.ctr * 10000) / 100,
      potential_clicks: Math.max(0, Math.round(r.impressions * 0.10) - r.clicks)
    }))
    .sort((a, b) => b.potential_clicks - a.potential_clicks)
    .slice(0, LIMIT);

  return {
    count: opportunities.length,
    criteria: `positions ${MIN_POSITION}-${MAX_POSITION}, min ${MIN_IMPRESSIONS} impressions`,
    opportunities,
    note: "potential_clicks is a rough estimate assuming ~10% CTR at the top of page 1. Directional only, not a forecast."
  };
}

