/** @CustomParams
{
    "rows": {
        "type": "string",
        "title": "Rows (JSON)",
        "required": true,
        "description": "JSON array of rows from the search analytics node"
    }
}
*/
export default async function run({ data }) {
  const parse = (v) => {
    if (Array.isArray(v)) return v;
    if (v == null || v === '' || v === 'null' || v === 'undefined') return [];
    try { const out = JSON.parse(v); return Array.isArray(out) ? out : []; } catch (e) { return []; }
  };
  const rows = parse(data.rows);

  const MIN_IMPRESSIONS = 100;
  const LIMIT           = 50;

  const CTR_BY_POSITION = {
    1: 0.28, 2: 0.15, 3: 0.11, 4: 0.08, 5: 0.06,
    6: 0.05, 7: 0.04, 8: 0.03, 9: 0.028, 10: 0.025
  };
  const expectedCtr = (position) => {
    if (position > 10) return 0.01;
    return CTR_BY_POSITION[Math.max(1, Math.round(position))] ?? 0.015;
  };

  const underperforming = rows
    .filter(r => r.impressions >= MIN_IMPRESSIONS)
    .map(r => {
      const expected = expectedCtr(r.position);
      const gap = r.ctr - expected;
      return {
        page:             r.keys[0],
        position:         Math.round(r.position * 10) / 10,
        impressions:      r.impressions,
        clicks:           r.clicks,
        ctr_pct:          Math.round(r.ctr * 10000) / 100,
        expected_ctr_pct: Math.round(expected * 10000) / 100,
        gap_pct:          Math.round(gap * 10000) / 100,
        missed_clicks:    Math.max(0, Math.round(r.impressions * expected) - r.clicks)
      };
    })
    .filter(r => r.gap_pct < 0)
    .sort((a, b) => b.missed_clicks - a.missed_clicks)
    .slice(0, LIMIT);

  return {
    count: underperforming.length,
    criteria: `pages with at least ${MIN_IMPRESSIONS} impressions and CTR below the typical rate for their average position`,
    underperforming,
    note: "Expected CTR is a generic industry benchmark, not a guarantee. Branded queries and SERP features (AI Overviews, featured snippets) can legitimately lower CTR. Treat this as a shortlist for manual review of titles and meta descriptions."
  };
}

