/** @CustomParams
{
    "query": {
        "type": "string",
        "title": "Query",
        "required": true,
        "description": "Current search query from the iterator"
    },
    "pages": {
        "type": "string",
        "title": "Pages (JSON)",
        "required": true,
        "description": "JSON array of page rows from search analytics"
    }
}
*/
export default async function run({ data, store }) {
  const query = data.query;
  const raw = data.pages;
  const pagesRaw = Array.isArray(raw) ? raw : JSON.parse(raw || '[]');

  const MIN_IMPRESSIONS = 20;
  const MAX_POSITION = 30;
  const MIN_PAGES = 2;

  const pages = pagesRaw
    .filter(p => p.impressions >= MIN_IMPRESSIONS && p.position <= MAX_POSITION)
    .map(p => ({
      page: p.keys[0],
      position: p.position,
      clicks: p.clicks,
      impressions: p.impressions
    }));

  if (pages.length < MIN_PAGES) {
    return { query, competing_pages: pages.length, skipped: true };
  }

  const byPosition = [...pages].sort((a, b) => a.position - b.position);
  const byClicks = [...pages].sort((a, b) => b.clicks - a.clicks);

  const entry = {
    query,
    competing_pages: pages.length,
    total_impressions: pages.reduce((n, p) => n + p.impressions, 0),
    total_clicks: pages.reduce((n, p) => n + p.clicks, 0),
    best_position: Math.round(byPosition[0].position * 10) / 10,
    conflict: byPosition[0].page !== byClicks[0].page,
    pages: byPosition.slice(0, 5).map(p => ({
      page: p.page,
      position: Math.round(p.position * 10) / 10,
      clicks: p.clicks,
      impressions: p.impressions
    }))
  };

  const acc = (await store.getGlobalVariable("kc_accumulator")) || [];
  acc.push(entry);
  await store.setGlobalVariable("kc_accumulator", acc);

  return { query, accumulated: entry };
}

