value.string:
/** @CustomParams
{
    "currentRows":   {"type":"string","title":"Current rows","required":true,
                      "description":"JSON array of query rows for the current period"},
    "previousRows":  {"type":"string","title":"Previous rows","required":true,
                      "description":"JSON array of query rows for the previous period"},
    "currentStart":  {"type":"string","title":"Current start"},
    "currentEnd":    {"type":"string","title":"Current end"},
    "previousStart": {"type":"string","title":"Previous start"},
    "previousEnd":   {"type":"string","title":"Previous end"},
    "comparable":    {"type":"string","title":"Equal length"}
}
*/
export default async function run({ data }) {
  const parse = (v) => {
    if (Array.isArray(v)) return v;
    if (v == null || v === '' || v === 'null' || v === 'undefined') return [];
    try { const out = JSON.parse(v); return Array.isArray(out) ? out : []; } catch (e) { return []; }
  };
  const cur  = parse(data.currentRows);
  const prev = parse(data.previousRows);

  const MIN_IMPRESSIONS = 10;
  const LIMIT           = 25;

  const keyOf   = r => r.keys[0];
  const curMap  = new Map(cur.map(r => [keyOf(r), r]));
  const prevMap = new Map(prev.map(r => [keyOf(r), r]));

  const rows = [];
  for (const k of new Set([...curMap.keys(), ...prevMap.keys()])) {
    const a = curMap.get(k);
    const b = prevMap.get(k);

    const clicksNow = a ? a.clicks : 0;
    const clicksWas = b ? b.clicks : 0;
    const imprNow   = a ? a.impressions : 0;
    const imprWas   = b ? b.impressions : 0;

    if (Math.max(imprNow, imprWas) < MIN_IMPRESSIONS) continue;

    rows.push({
      query:              k,
      status:             !b ? 'new' : !a ? 'lost'
                            : clicksNow > clicksWas ? 'up'
                            : clicksNow < clicksWas ? 'down' : 'flat',
      clicks_now:         clicksNow,
      clicks_before:      clicksWas,
      clicks_delta:       clicksNow - clicksWas,
      clicks_change_pct:  clicksWas ? Math.round((clicksNow - clicksWas) / clicksWas * 1000) / 10 : null,
      impressions_now:    imprNow,
      impressions_before: imprWas,
      impressions_delta:  imprNow - imprWas,
      ctr_now_pct:        a ? Math.round(a.ctr * 10000) / 100 : 0,
      ctr_before_pct:     b ? Math.round(b.ctr * 10000) / 100 : 0,
      position_now:       a ? Math.round(a.position * 10) / 10 : null,
      position_before:    b ? Math.round(b.position * 10) / 10 : null,
      position_delta:     (a && b) ? Math.round((a.position - b.position) * 10) / 10 : null
    });
  }

  const gainers = rows
    .filter(r => r.clicks_delta > 0)
    .sort((x, y) => y.clicks_delta - x.clicks_delta)
    .slice(0, LIMIT);

  const losers = rows
    .filter(r => r.clicks_delta < 0)
    .sort((x, y) => x.clicks_delta - y.clicks_delta)
    .slice(0, LIMIT);

  const sum = f => rows.reduce((n, r) => n + f(r), 0);
  const clicksNow = sum(r => r.clicks_now);
  const clicksWas = sum(r => r.clicks_before);

  return {
    periods: {
      current:      `${data.currentStart} — ${data.currentEnd}`,
      previous:     `${data.previousStart} — ${data.previousEnd}`,
      equal_length: String(data.comparable) === 'true'
    },
    summary: {
      clicks_now:         clicksNow,
      clicks_before:      clicksWas,
      clicks_delta:       clicksNow - clicksWas,
      clicks_change_pct:  clicksWas ? Math.round((clicksNow - clicksWas) / clicksWas * 1000) / 10 : null,
      impressions_now:    sum(r => r.impressions_now),
      impressions_before: sum(r => r.impressions_before),
      queries_up:         rows.filter(r => r.status === 'up').length,
      queries_down:       rows.filter(r => r.status === 'down').length,
      queries_new:        rows.filter(r => r.status === 'new').length,
      queries_lost:       rows.filter(r => r.status === 'lost').length
    },
    gainers,
    losers,
    note: "Totals are summed from query-level rows and therefore exclude anonymized queries, so they will not match the totals shown in the Search Console UI. Queries marked 'new' or 'lost' may simply have crossed Google's anonymization threshold rather than genuinely appeared or disappeared. A negative position_delta means the position improved."
  };
}

