/** @CustomParams
{
    "siteUrl":       {"type":"string","title":"Site URL","required":true,
                      "description":"Property URL as defined in Search Console"},
    "currentEnd":    {"type":"string","title":"Current period end",
                      "description":"YYYY-MM-DD. Defaults to today minus 3 days (GSC lag)"},
    "currentStart":  {"type":"string","title":"Current period start",
                      "description":"YYYY-MM-DD. Defaults to 28 days before currentEnd"},
    "previousEnd":   {"type":"string","title":"Previous period end",
                      "description":"YYYY-MM-DD. Optional, calculated automatically"},
    "previousStart": {"type":"string","title":"Previous period start",
                      "description":"YYYY-MM-DD. Optional, calculated automatically"}
}
*/
export default async function run({ data }) {
  const DAY = 86400000;
  const iso   = ms => new Date(ms).toISOString().slice(0, 10);
  const clean = v  => String(v || '').trim().slice(0, 10);
  const valid = v  => /^\d{4}-\d{2}-\d{2}$/.test(v);
  const shift = (d, n) => iso(new Date(d + 'T00:00:00Z').getTime() + n * DAY);
  const span  = (a, b) =>
    Math.round((new Date(b + 'T00:00:00Z') - new Date(a + 'T00:00:00Z')) / DAY) + 1;

  // Текущий период. По умолчанию — последние 28 дней с поправкой на лаг GSC
  let curEnd = clean(data.currentEnd);
  if (!valid(curEnd)) curEnd = iso(Date.now() - 3 * DAY);

  let curStart = clean(data.currentStart);
  if (!valid(curStart)) curStart = shift(curEnd, -27);

  const curDays = span(curStart, curEnd);

  // Предыдущий период. Если не задан — берём равный отрезок вплотную перед текущим
  let prevEnd = clean(data.previousEnd);
  if (!valid(prevEnd)) prevEnd = shift(curStart, -1);

  let prevStart = clean(data.previousStart);
  if (!valid(prevStart)) prevStart = shift(prevEnd, -(curDays - 1));

  const prevDays = span(prevStart, prevEnd);

  return {
    siteUrl:       data.siteUrl,
    currentStart:  curStart,
    currentEnd:    curEnd,
    previousStart: prevStart,
    previousEnd:   prevEnd,
    currentDays:   curDays,
    previousDays:  prevDays,
    comparable:    curDays === prevDays
  };
}

